def has_balanced_parentheses(text):
    balance = 0
    for char in text:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def second_largest(numbers):
    unique = sorted(set(numbers), reverse=True)
    if len(unique) < 2:
        raise ValueError('At least two distinct numbers are required')
    return unique[1]

def word_frequency(sentence):
    counts = {}
    for word in sentence.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def rotate_list(numbers, k):
    if not numbers:
        return []
    k = k % len(numbers)
    return numbers[-k:] + numbers[:-k] if k else numbers[:]

def remove_duplicates(items):
    result = []
    seen = set()
    for item in items:
        if item not in seen:
            result.append(item)
            seen.add(item)
    return result

def find_missing_number(numbers):
    n = len(numbers)
    return n * (n + 1) // 2 - sum(numbers)
